/// <reference lib="dom" />
/// <reference lib="dom.iterable" />
/// <reference lib="es2023" />

import { loadFont as loadInter } from "@remotion/google-fonts/Inter";
import {
  type ComponentProps,
  createContext,
  type CSSProperties,
  forwardRef,
  type ReactNode,
  useContext,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  getRemotionEnvironment,
  Interactive,
  type InteractivitySchema,
  interpolate,
  Sequence,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import {
  clampChroma,
  converter,
  formatRgb,
  interpolate as culoriInterpolate,
  parse,
  type Rgb,
} from "culori";
import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { loadFont as loadInstrumentSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadOutfit } from "@remotion/google-fonts/Outfit";
import { loadFont as loadSpaceGrotesk } from "@remotion/google-fonts/SpaceGrotesk";

const toRgb = converter("rgb");

/**
 * Whether to warn. Read through `globalThis`, never a bare `process`: a Vite
 * project defines no `process`, so the bare name threw a ReferenceError on the
 * very input it meant to warn about — and a stock Remotion project has no Node
 * types, so the bare name was also a type error in every install.
 */
function isDev(): boolean {
  const env = (globalThis as { process?: { env?: { NODE_ENV?: string } } })
    .process?.env;
  return env?.NODE_ENV !== "production";
}

function resolveColorString(s: string): string {
  const trimmed = s.trim();
  if (trimmed.startsWith("var(")) {
    if (isDev()) {
      console.warn(
        `mixOklch cannot resolve CSS variable "${trimmed}" under Remotion's per-frame render. ` +
          "Animated colors must be concrete oklch/hex/rgb values supplied via the theme. " +
          "Falling back to the JS default.",
      );
    }
    return "#000";
  }
  if (!parse(trimmed)) {
    if (isDev()) {
      console.warn(`mixOklch could not parse "${trimmed}"; using black.`);
    }
    return "#000";
  }
  return trimmed;
}

function mixOklch(a: string, b: string, t: number): string {
  const mixed = clampChroma(
    culoriInterpolate(
      [resolveColorString(a), resolveColorString(b)],
      "oklch",
    )(t),
    "oklch",
    "rgb",
  );
  return toCss(toRgb(mixed));
}

function toCss(color: Rgb): string {
  return formatRgb(color);
}

/**
 * The type faces a scene's `fontFamily` may name.
 *
 * ## Why an allowlist and not a free string
 *
 * Every component in this registry loads its face through
 * `@remotion/google-fonts` rather than a CSS variable, for the reason spelled
 * out at the top of each one: a Remotion bundle has none of the app's CSS, so
 * `var(--font-…)` gets you the right face in the Player and a **fallback in the
 * mp4**. A bare family name handed to a component has exactly the same problem
 * — the browser preview finds it, the render does not, and the bug is invisible
 * until someone plays the file.
 *
 * So a name only counts as a font here if this module has loaded it. Values map
 * label → the real CSS family string `loadFont` returns, which is not always the
 * label ("Instrument Serif", not "InstrumentSerif").
 *
 * ## A raw stack still works
 *
 * `resolveFont` passes anything it does not recognise straight through, so a
 * caller who has loaded their own face — a brand font, a local `@font-face` —
 * names it directly and gets it. The allowlist is the safe path, not the only one.
 *
 * ponytail: all six load at module scope, so a render fetches six latin subsets
 * whether or not the video uses them. Move to a lazy per-family `loadFont()` if
 * bundle time ever shows up in a render trace.
 */
const FONTS: Record<string, string> = {
  Inter: loadInter("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Geist: loadGeist("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  "Space Grotesk": loadSpaceGrotesk("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Outfit: loadOutfit("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Montserrat: loadMontserrat("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  // 400 is the only weight this family ships. Asking for 600 throws.
  "Instrument Serif": loadInstrumentSerif("normal", {
    weights: ["400"],
    subsets: ["latin"],
  }).fontFamily,
};

/**
 * What a select control offers. `DEFAULT_FONT` first: a scene's own face is a
 * design decision, so the knob has to have an "off", and it has to be the
 * value it ships at.
 */
const DEFAULT_FONT = "Default";

/**
 * Label → loaded CSS family. Anything unrecognised passes through unchanged, so
 * a caller's own stack is never swallowed. `undefined` in, `undefined` out —
 * that is the signal for "keep the component's own face".
 */
const resolveFont = (name?: string): string | undefined =>
  !name || name === DEFAULT_FONT ? undefined : (FONTS[name] ?? name);

interface KitTheme {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  popover: string;
  popoverForeground: string;
  primary: string;
  primaryForeground: string;
  secondary: string;
  secondaryForeground: string;
  muted: string;
  mutedForeground: string;
  accent: string;
  accentForeground: string;
  destructive: string;
  destructiveForeground: string;
  border: string;
  input: string;
  ring: string;
  radius: number;
  /**
   * The face every text component paints with, as a label from `fonts.ts` or a
   * CSS family the caller has loaded themselves.
   *
   * Optional and defaulted to nothing on purpose: unset, each component keeps
   * the face it was designed around, so adding this token changed no existing
   * render. Set it on `KitUIProvider` and one value re-skins a whole
   * timeline — which is the only reason it lives on the theme rather than
   * staying a per-component prop.
   */
  fontFamily?: string;
}

/**
 * The shadcn token set, as concrete values.
 *
 * ## These are a mirror of `app/globals.css`, and that is the whole point
 *
 * A component we ship lands next to somebody's `Button` and `Input`, and those
 * paint from the CSS custom properties in `globals.css`. A scene that paints
 * from a *different* set of greys is a scene that clashes with the app it was
 * installed into — which is exactly what happened here: this file was written
 * first, `globals.css` was later re-skinned warm, and for a while the site and
 * the videos it sells were two different products.
 *
 * So every value below is the **literal string** from the corresponding
 * `--token` in `app/globals.css` (`:root` for light, `.dark` for dark). Hex, not
 * oklch, purely so that drift is a string comparison — if the two files ever
 * disagree again, `pnpm run check:tokens` says so and prints the pairs.
 *
 * ## Why not just read `var(--token)`?
 *
 * Because a Remotion bundle has none of the app's CSS, so `var()` resolves to
 * nothing under the headless renderer and cannot be interpolated by `mixOklch`
 * at all (see the guard in `color.ts`). Concrete values are not a shortcut here,
 * they are the only thing that survives a render. Users on a different palette
 * override via `KitUIProvider` or a component's `theme` prop.
 *
 * ## `radius` is the one value that flows the other way
 *
 * `globals.css` sets `--radius: 0.28rem` *so that* its `--radius-3xl` step lands
 * on this 10 — see the note beside it there. It is not drift; do not "fix" it.
 */
const defaultLightTheme: KitTheme = {
  background: "#faf9f6", // page — warm off-white
  foreground: "#141414", // text
  card: "#ffffff", // surface on the page
  cardForeground: "#141414",
  popover: "#ffffff",
  popoverForeground: "#141414",
  primary: "#1d6bff", // accent blue
  primaryForeground: "#ffffff",
  secondary: "#f2f0eb", // subtle fill
  secondaryForeground: "#141414",
  muted: "#f2f0eb",
  mutedForeground: "#6e6a63", // secondary text, leading icons
  accent: "#f2f0eb", // hover wash
  accentForeground: "#141414",
  destructive: "#d92d20",
  // `globals.css` defines no --destructive-foreground; white is the only thing
  // that reads on #d92d20, and shadcn's own default agrees.
  destructiveForeground: "#ffffff",
  border: "#d9d9d9", // hairline
  input: "#d9d9d9",
  ring: "#1d6bff",
  radius: 10,
};

const defaultDarkTheme: KitTheme = {
  background: "#0a0a0b", // page — near-black
  foreground: "#fafafa", // text
  card: "#141417", // surface, a shade above the page
  cardForeground: "#fafafa",
  popover: "#141417",
  popoverForeground: "#fafafa",
  primary: "#1d6bff", // the same accent blue in both modes
  primaryForeground: "#ffffff",
  secondary: "#1d1d21", // subtle fill
  secondaryForeground: "#fafafa",
  muted: "#1b1b1f",
  mutedForeground: "#a1a1aa", // secondary text, leading icons
  accent: "#1d1d21", // hover wash
  accentForeground: "#fafafa",
  destructive: "#f97066",
  destructiveForeground: "#fafafa",
  border: "#26272b", // hairline — separation is borders, not shadows
  input: "#26272b",
  ring: "#1d6bff",
  radius: 10,
};

interface KitThemeContextValue {
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
}

const KitThemeContext = createContext<KitThemeContextValue>({});

function useKitTheme(
  override?: Partial<KitTheme>,
  modeOverride?: "light" | "dark",
): KitTheme {
  const ctx = useContext(KitThemeContext);
  const mode = modeOverride ?? ctx.mode ?? "light";
  const base = mode === "dark" ? defaultDarkTheme : defaultLightTheme;
  return { ...base, ...ctx.theme, ...override };
}

interface TextRevealProps {
  /** The sentence to assemble. Its first word leads the reveal. */
  text?: string;
  /** Final font size in px (the size the line settles at). */
  fontSize?: number;
  /** Overrides the design system's `foreground`. */
  color?: string;
  fontWeight?: number | string;
  /** Design-system token overrides. */
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
  /**
   * The face this scene paints its words in — a label from `fonts.ts`
   * ("Inter", "Space Grotesk", "Instrument Serif") or a CSS family you have
   * loaded yourself. Unset, the scene keeps the face it was designed around.
   *
   * Overrides `theme.fontFamily`, which is how a brand kit re-skins a whole
   * timeline from one value.
   */
  fontFamily?: string;
  /** How much larger the lead word starts (2 = twice the final size). */
  initialScale?: number;
  /** Frames the lead word fades in over at the very start. */
  introDuration?: number;
  /**
   * Frames the lead word spends big and centred, drifting toward the viewer,
   * before it falls back.
   */
  holdDuration?: number;
  /** How far toward the viewer the lead word drifts during the hold (1.06 = 6% larger). */
  pushScale?: number;
  /** Frames the lead word takes to fall back from its peak to its final size. */
  recedeDuration?: number;
  /**
   * Frames the line takes to slide left into its resting place. Starts with the
   * recede but runs well past it, so the line barely moves while the lead word
   * is still falling back and only travels once it has landed.
   */
  assembleDuration?: number;
  /** Frames after the recede begins before the second word pushes in. */
  wordDelay?: number;
  /** Frames between each trailing word pushing in. */
  wordStagger?: number;
  /** Frames a trailing word takes to push into its slot. */
  wordDuration?: number;
  /** How far right of its slot a trailing word starts, in em. */
  wordPush?: number;
  /**
   * Frames a trailing word fades in over. Deliberately tiny — the word should
   * read as _pushed_ into place, not faded in. Raise it for a softer arrival.
   */
  wordFade?: number;
  /** Resting letter-spacing (CSS value, em recommended). */
  letterSpacing?: string;
  speed?: number;
  className?: string;
}

/**
 * The lead word's drift toward the viewer: decelerating, so it hangs at the
 * peak for a beat before it falls back.
 */
const PUSH_EASE = Easing.bezier(0.25, 1, 0.5, 1);

/**
 * Shared curve for the recede and the slide-left. Heavily eased in — barely 10%
 * travelled at a third of the way through — so a long `assembleDuration` keeps
 * the line practically still while the lead word falls back, then carries it
 * left and decelerates to a dead stop. No bounce.
 */
const ZOOM_EASE = Easing.bezier(0.5, 0, 0.05, 1);

/** A trailing word's push into its slot: quick off the mark, long soft landing. */
const WORD_EASE = Easing.bezier(0.22, 0.8, 0.36, 1);

/**
 * Cinematic "zoom-out from the lead word" reveal, in four beats:
 *
 * 1. The lead word fades in large and centred — close to the viewer.
 * 2. It drifts a little _closer_ still, hanging at the peak.
 * 3. It falls back to its final size, roughly in place.
 * 4. Only once it has landed does the line travel left, while the trailing words
 *    push in one by one from the right and settle.
 *
 * Beats 3 and 4 start on the same frame but run on very different clocks: the
 * recede is short, the slide is long and heavily eased in, which is what makes
 * the word read as going _back_ first and moving left second rather than doing
 * both at once. The trailing words stay invisible until `wordDelay` frames into
 * the recede — so none of them show up mid-flight while the lead word is still
 * travelling — then cut in a push-distance right of their slot and slide home.
 *
 * Only `scale`, `translate` and `opacity` animate — nothing reflows — so it
 * stays GPU-cheap with a constant baseline and no layout shift.
 */
function TextReveal({
  text = "Meet Acme Billing",
  fontSize = 72,
  color,
  fontWeight = 600,
  theme,
  mode,
  fontFamily,
  initialScale = 2.3,
  introDuration = 6,
  holdDuration = 12,
  pushScale = 1.06,
  recedeDuration = 14,
  assembleDuration = 30,
  wordDelay = 7,
  wordStagger = 4,
  wordDuration = 14,
  wordPush = 0.5,
  wordFade = 2,
  letterSpacing = "-0.03em",
  speed = 1,
  className,
}: TextRevealProps) {
  const frame = useCurrentFrame() * speed;
  const { width } = useVideoConfig();
  const t = useKitTheme(theme, mode);
  const face =
    resolveFont(fontFamily ?? t.fontFamily) ??
    "-apple-system, BlinkMacSystemFont, sans-serif";
  const fill = color ?? t.foreground;

  // The lead word is centred in the frame while big, then lands at its natural
  // spot in the line. That needs the line's rendered width and where the lead
  // word's centre sits inside it — both constant across frames, so measure once
  // and hold the render until they're known.
  const lineRef = useRef<HTMLSpanElement>(null);
  const leadRef = useRef<HTMLSpanElement>(null);
  const [handle] = useState(() => delayRender("text-reveal: measure line"));
  const baselineRef = useRef<HTMLSpanElement>(null);
  const [metrics, setMetrics] = useState<{
    lineWidth: number;
    leadRatio: number;
    /** Distance from the top of the line box down to the text baseline. */
    baseline: number;
  } | null>(null);

  // Measure the natural line geometry. offsetWidth / offsetLeft are layout px,
  // unaffected by the animated transform or the Player's display scaling, so they
  // give the unscaled line width and the lead word's centre directly.
  useEffect(() => {
    const line = lineRef.current;
    const lead = leadRef.current;
    if (!line || !lead) {
      continueRender(handle);
      return;
    }
    const lineWidth = line.offsetWidth;
    const leadCenter = lead.offsetLeft + lead.offsetWidth / 2;
    // An empty, zero-sized inline-block sits with its bottom edge on the text
    // baseline, so its offsetTop *is* the baseline — read from the font's real
    // metrics rather than guessed from a line-height ratio.
    const baseline = baselineRef.current?.offsetTop ?? line.offsetHeight * 0.8;
    setMetrics({ lineWidth, leadRatio: leadCenter / lineWidth, baseline });
  }, [handle]);

  // Release the render only after the measurement has re-rendered, so the very
  // first captured frame already carries the correct geometry (no blank frame).
  useEffect(() => {
    if (metrics) continueRender(handle);
  }, [metrics, handle]);

  const words = text.split(" ").filter(Boolean);

  /**
   * Two things make a browser's scaled text look stuck and shaky, and both are
   * the type being quantised rather than the animation being wrong.
   *
   * **The stick.** The glyph rasteriser snaps each glyph's origin to the pixel
   * grid — quarter-pixel precision horizontally, and none at all vertically. So a
   * scale that moves the baseline makes the type climb the grid in whole-pixel
   * steps: during the slow ends of an eased curve the baseline drifts a fraction
   * of a pixel per frame, which rounds to nothing for several frames and then to a
   * whole pixel at once. Pivoting the scale *on the baseline* means the baseline's
   * device Y never changes, so there is nothing to snap.
   *
   * **The shake.** Hinting distorts each glyph's outline so its stems land on
   * whole pixels. As the size slides, every stem re-snaps to a different grid and
   * the letterforms visibly change shape frame to frame — they boil.
   * `text-rendering: geometricPrecision` turns hinting off and renders the outline
   * as it actually is.
   *
   * Measured on the sibling component: vertical judder 0.296px → 0.005px, and the
   * shape invariant steadied from 3.41% drift to 0.22%.
   */

  const ready = metrics !== null;
  const leadRatio = metrics?.leadRatio ?? 0.14;
  const lineWidth = metrics?.lineWidth ?? width * 0.5;
  // Distance from the top of the line box down to the text baseline — the one
  // point the scale must not move.
  const baseline = metrics?.baseline ?? fontSize * 0.88;

  // The lead word falls back and the line starts sliding on the same frame.
  const zoomStart = holdDuration;
  // How far the line has to travel to carry the lead word's centre from the
  // frame centre to its natural spot in the sentence.
  const slideDistance = lineWidth * (0.5 - leadRatio);

  return (
    <AbsoluteFill
      showInTimeline={false}
      style={{
        alignItems: "center",
        justifyContent: "center",
        background: "transparent",
      }}
    >
      <span
        ref={lineRef}
        className={className}
        style={{
          position: "relative",
          display: "inline-block",
          fontSize,
          fontWeight,
          color: fill,
          letterSpacing,
          lineHeight: 1.1,
          whiteSpace: "nowrap",
          fontFamily: face,
          // Pivot on the lead word's centre horizontally — so the line scales out
          // from that word and it stays planted — and on the baseline vertically,
          // which is the point that must not move. See above.
          transformOrigin: `${leadRatio * 100}% ${baseline}px`,
          // Drift toward the viewer, then the fall back. The two curves never
          // overlap — the first clamps at the peak once the recede starts, the
          // second is 0 until then — so they sum into one continuous scale
          // running initialScale → peak → 1.
          scale:
            interpolate(
              frame,
              [0, holdDuration],
              [initialScale, initialScale * pushScale],
              {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
                easing: PUSH_EASE,
              },
            ) +
            interpolate(
              frame,
              [zoomStart, zoomStart + recedeDuration],
              [0, 1 - initialScale * pushScale],
              {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
                easing: ZOOM_EASE,
              },
            ),
          // The slide left: same start frame as the recede, but it runs about
          // twice as long on a heavily eased-in curve, so the line holds its
          // ground while the lead word falls back and only travels once it has
          // landed.
          translate: `${interpolate(
            frame,
            [zoomStart, zoomStart + assembleDuration],
            [slideDistance, 0],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: ZOOM_EASE,
            },
          )}px`,
          opacity: ready ? 1 : 0,
          // Hinting off: renders each outline as it actually is, so the
          // letterforms stop re-snapping to the pixel grid as the size slides.
          // Also forces sub-pixel glyph positioning, which Blink otherwise only
          // enables above a device scale factor of 1 — and a render is exactly 1.
          textRendering: "geometricPrecision",
          // Rendering and live playback want opposite things here, so give each
          // what it needs.
          //
          // A render has no time budget: the browser re-shapes and re-rasterises
          // every glyph at every new size, which is why the type stays genuinely
          // crisp, and the two fixes above are what make that smooth. Compositing
          // it would only replace real type with a rescaled texture — and worse,
          // a render is spread across parallel browser tabs, each of which
          // inherits a stale raster from whatever scale it drew last, so the same
          // frame comes out differently depending on which tab drew it.
          //
          // The Player is the opposite: one continuous tab, and roughly eight
          // milliseconds a frame on a 120Hz screen. Re-shaping a line of type at
          // a brand-new size every frame is the most expensive way to draw text,
          // and a frame that misses the budget is simply shown for the wrong
          // length of time — stutter that no amount of CSS can fix. So for live
          // playback, hand the scale to the compositor: measured on a single
          // continuous tab it is smooth (0.016px of judder) with no loss of
          // sharpness at all.
          ...(getRemotionEnvironment().isRendering
            ? null
            : { willChange: "transform" as const }),
        }}
      >
        {words.map((word, i) => {
          const isLead = i === 0;
          // Each trailing word sits out most of the recede, then pushes in from
          // the right into its slot. The lead word is the anchor: it never
          // pushes, and it is the only word visible until `wordDelay`.
          const pushStart = zoomStart + wordDelay + (i - 1) * wordStagger;
          const opacity = isLead
            ? interpolate(frame, [0, introDuration], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              })
            : interpolate(frame, [pushStart, pushStart + wordFade], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              });
          return (
            <span
              // biome-ignore lint/suspicious/noArrayIndexKey: words are positional and never reorder
              key={i}
              ref={isLead ? leadRef : undefined}
              style={{
                display: "inline-block",
                opacity,
                translate: isLead
                  ? undefined
                  : `${interpolate(
                      frame,
                      [pushStart, pushStart + wordDuration],
                      [wordPush * fontSize, 0],
                      {
                        extrapolateLeft: "clamp",
                        extrapolateRight: "clamp",
                        easing: WORD_EASE,
                      },
                    )}px`,
              }}
            >
              {word}
              {i < words.length - 1 ? " " : ""}
            </span>
          );
        })}
        {/* Baseline ruler. An empty, zero-sized inline-block aligns its bottom
            edge to the text baseline, so `offsetTop` reads the baseline straight
            off the font's real metrics. Zero-sized, so it changes no layout. */}
        <span
          ref={baselineRef}
          style={{ display: "inline-block", width: 0, height: 0 }}
        />
      </span>
    </AbsoluteFill>
  );
}

// ── The opening ──────────────────────────────────────────────────────────────

/**
 * Frames 0 to `CUT_AT` belong to `text-reveal`, which this component mounts
 * rather than reimplements — so its schedule lives there, not here.
 *
 * What the reference does in those frames is a *typewriter*: a constant
 * 1.5467 frames per character with the final full stop held back five frames,
 * each glyph landing at 1.178x and settling over five, arriving near-black with
 * a violet cast (#292541) rather than at the caret's own light violet. That is
 * documented because it was measured and is worth keeping, not because anything
 * below consumes it — `text-reveal` assembles word by word instead, which is a
 * different animation and a deliberate choice.
 */

// ── The slide ────────────────────────────────────────────────────────────────

/**
 * The re-centring move is ONE continuous curve, and it starts before the cut.
 *
 * This is the correction that mattered most. The obvious reading is "the lead is
 * cut, then what is left slides back to centre", which makes the motion start at
 * the cut. It does not. The line is already moving five frames earlier, and one
 * 16-frame cubic-bezier fits all 17 frames of it — through the cut — to a mean
 * error of 0.067px, max 0.23px.
 *
 * Alternatives on the same data: exponential decay 8.76px, a Remotion spring
 * with five free parameters 2.07px, degree-6 polynomial 1.60px, cubic 6.94px.
 * The bezier is better by two orders of magnitude, so this is not a close call.
 *
 * The consequence for the implementation: **the cut is a visibility change, not
 * a position change.** Residuals across it are +0.080 (before) and -0.108
 * (after) — nothing jumps. Earlier versions modelled a "pre-cut drift" and a
 * separate slide, which is the same curve described as two and fitted twice.
 */
const SLIDE_FROM = 39;
const SLIDE_TO = 55;
const SLIDE_BEZIER = [0.3438, 0.0294, 0.032, 0.9269] as const;

/** The lead stops being drawn here. Position is unaffected — see `SLIDE_BEZIER`. */
const CUT_AT = 44;

// ── The morph ────────────────────────────────────────────────────────────────

const MORPH_FROM = 56;
const MORPH_TO = 67;

// ── The exit ─────────────────────────────────────────────────────────────────

/**
 * The exit drift: geometric per-frame velocity, i.e. an exponential ease-in.
 *
 * Starts at frame 72 — the frames before it are static to within 0.005px, and
 * frame 73 is the first displaced one at 0.73px. Sub-pixel displacements are
 * 0.73, 1.99, 3.70, 6.05, 9.76, 16.28, 30.03, 54.2; the integer bounding box
 * reads those as 1,2,3,7,9,16,29,54 because motion blur erodes a thresholded
 * edge, which is why an earlier hand-fit had both the start frame and the first
 * step wrong.
 *
 * Fit: 0.36px mean error. Quadratic is 8.60px, cubic 3.42px, easeInQuart 1.72px.
 */
const EXIT_FROM = 72;
const EXIT_RATIO = 1.76456;
const EXIT_COEFF = 1.3194;

/** The cut to the final phrase. */
const CUT2_AT = 81;
/** Each flood stage. Both are single-frame cuts to a flat colour, not ramps. */
const FLOOD_STAGE_FRAMES = 4;

const { fontFamily: SANS } = loadInter("normal", {
  weights: ["400", "700"],
  subsets: ["latin"],
});

export interface TypeMorphProps {
  /**
   * The line as it is typed. Everything up to and including `lead` is cut away
   * once typing finishes, which is what leaves the emphasis alone on screen.
   */
  lead?: string;
  /** The emphasised tail of the typed line — this is what survives the cut. */
  emphasis?: string;
  /** What the emphasis morphs into, letter by letter. */
  morphTo?: string;
  /**
   * What is left after the second cut. Empty ends the beat on the bare flood.
   */
  finally_?: string;
  /**
   * Whether the final phrase survives into the flood.
   *
   * The reference carries it across; off is the cleaner ending, and it is the
   * default because a word sitting on a full-bleed colour for four frames reads
   * as a leftover rather than as a beat.
   */
  wordOnFlood?: boolean;
  /** Accepted, not drawn: the caret and fresh glyphs take the ink colour. */
  accent?: string;
  /**
   * Two flat colours to flood the frame with at the end, or `false` to end on
   * paper — the default.
   *
   * The reference floods; off is the quieter ending and the one that composes,
   * because a beat that hands the next scene a full-bleed colour has decided
   * what that scene opens on.
   *
   * Two flat colours rather than a ramp: the reference arrives at 99% frame
   * coverage inside a single frame and then steps once. A crossfade between them
   * would put a half-transparent wash over the type for several frames, and
   * there is no reading of that except the screen dimming.
   */
  flood?: [string, string] | false;
  /**
   * The page.
   *
   * Defaults to the theme's background so the component belongs in whatever
   * project installs it. The reference's paper is a plain near-white (#f7f7f7 to
   * #fafafa across the beat), not the warm off-white the token carries, so the
   * preview passes its own.
   */
  background?: string;
  /** The type. Defaults to the theme's foreground. */
  ink?: string;
  /**
   * The opening line is rendered by `text-reveal` itself.
   *
   * Not a reimplementation of it, and not its helper functions rebuilt into a
   * second animator — the component, mounted. Everything in `reveal` is passed
   * to it untouched, so its lead-word push, its recede and its assemble are
   * exactly what that component does anywhere else, and there is nothing here
   * that can drift away from it.
   */
  reveal?: Omit<
    React.ComponentProps<typeof TextReveal>,
    "text" | "theme" | "mode" | "color" | "fontSize"
  >;
  /**
   * Cap-to-descender height as a fraction of the frame height.
   *
   * 0.1256, not the 0.139 the reference's raw ink height suggests: measured back
   * from the rendered line width against the reference's at the same frame, mine
   * came out 12.7% wide at 0.139 and 4% narrow at 0.1233, because ink height
   * includes the descender and the face's
   * own metrics differ from the reference's.
   */
  size?: number;
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
  /**
   * The face this scene paints its words in — a label from `fonts.ts`
   * ("Inter", "Space Grotesk", "Instrument Serif") or a CSS family you have
   * loaded yourself. Unset, the scene keeps the face it was designed around.
   *
   * Overrides `theme.fontFamily`, which is how a brand kit re-skins a whole
   * timeline from one value.
   */
  fontFamily?: string;
}

/**
 * `will-change` is right for the Player and wrong for the render — a render
 * draws each frame in a different tab, and a promoted layer hands that tab a
 * stale raster from whatever scale it last drew.
 */
const promoted = getRemotionEnvironment().isRendering
  ? null
  : ({ willChange: "transform" } as const);

/**
 * Hinting bends each glyph so its stems land on whole pixels, so as anything
 * moves the letterforms re-snap and boil. This also forces sub-pixel glyph
 * positioning, which Blink otherwise only enables above a device scale factor of
 * 1 — and a render is exactly 1, so without it every glyph in the morph would
 * land on a whole pixel and the travel would stutter.
 */
const CRISP: CSSProperties = {
  textRendering: "geometricPrecision",
  WebkitFontSmoothing: "antialiased",
};

/** Moderate decelerate. Quint/expo spend frames below half a pixel, which rasterise identically. */
const EASE = Easing.bezier(0.2, 0.6, 0.35, 1);

/**
 * Pair each glyph of `to` with a glyph of `from` that can travel to it.
 *
 * Greedy nearest-unused match on the character itself. It is not the optimal
 * assignment and does not need to be — what the eye reads is *continuity*, that
 * some letters persisted rather than the whole line being replaced, and a
 * nearest match delivers that while an optimal one costs a matrix and looks the
 * same. Unmatched targets fade up in place; unmatched sources fade out in place.
 */
function pairGlyphs(from: string, to: string): (number | null)[] {
  const used = new Set<number>();
  return [...to].map((ch, ti) => {
    let best: number | null = null;
    let bestDist = Infinity;
    for (let fi = 0; fi < from.length; fi += 1) {
      if (used.has(fi) || from[fi] !== ch) continue;
      const dist = Math.abs(fi - ti);
      if (dist < bestDist) {
        bestDist = dist;
        best = fi;
      }
    }
    if (best !== null) used.add(best);
    return best;
  });
}

/** Per-glyph x offsets of a string, measured in the real face at the real size. */
function useGlyphOffsets(strings: string[], fontSize: number, face: string) {
  const ref = useRef<HTMLDivElement>(null);
  const [offsets, setOffsets] = useState<number[][] | null>(null);
  // Every frame of a render is a fresh mount, so a plain effect + state lets the
  // frame be captured *before* the measurement has re-rendered — the glyphs are
  // then placed with no offsets at all and the frame comes out blank or short.
  // `delayRender` holds the capture until the second render has happened.
  const [handle] = useState(() => delayRender("type-morph: measuring glyphs"));

  useLayoutEffect(() => {
    const root = ref.current;
    if (!root) return;
    // `offsetLeft` is layout px and unaffected by transforms — which is exactly
    // why it is the right tool for measuring a line that is about to be
    // transformed, which is exactly why it is the right tool for measuring a
    // line that is about to be transformed.
    setOffsets(
      [...root.children].map((line) =>
        [...(line as HTMLElement).children].map(
          (g) => (g as HTMLElement).offsetLeft,
        ),
      ),
    );
  }, []);

  // Only once the measured offsets are actually in the tree.
  useLayoutEffect(() => {
    if (offsets) continueRender(handle);
  }, [offsets, handle]);

  const probe = (
    <div
      ref={ref}
      aria-hidden
      style={{
        position: "absolute",
        visibility: "hidden",
        pointerEvents: "none",
        whiteSpace: "pre",
        fontFamily: face,
        fontSize,
        letterSpacing: "-0.035em",
        ...CRISP,
      }}
    >
      {strings.map((s) => (
        <div key={s} style={{ whiteSpace: "pre" }}>
          {[...s].map((ch, i) => (
            // biome-ignore lint/suspicious/noArrayIndexKey: glyph position is the identity here
            <span key={i} style={{ display: "inline-block" }}>
              {ch === " " ? " " : ch}
            </span>
          ))}
        </div>
      ))}
    </div>
  );

  return { probe, offsets };
}

/**
 * A headline that types itself, sheds its lead, morphs letter by letter, and
 * ends under a colour flood.
 *
 * Four mechanics on one timeline, each measured off a reference frame by frame
 * (see `timeline.ts` for the signals and the numbers they produced):
 *
 * 1. **Typing.** The line is centre-anchored, so it grows in both directions
 *    rather than running to the right. Freshly landed glyphs arrive in the
 *    accent colour and cool to ink over four frames, which is what gives the
 *    typing a moving warm edge instead of a hard cursor.
 * 2. **The cut.** The lead is removed in a single frame, not animated out. What
 *    *is* animated is the slide back to centre that follows it.
 * 3. **The morph.** Glyphs shared between the two phrases travel from where they
 *    were to where they belong; the rest cross-fade in place.
 * 4. **The flood.** Two flat colours, four frames each.
 *
 * Every glyph position is measured in the real face at the real size behind a
 * hidden probe, because a morph built on estimated advance widths lands each
 * letter a pixel or two off and reads as a wobble.
 */
function TypeMorphScene({
  lead = "Not just ",
  emphasis = "communicator.",
  morphTo = "something more.",
  finally_ = "more.",
  wordOnFlood = false,
  background,
  ink,
  reveal,
  flood = false,
  size = 0.1256,
  theme,
  mode,
  fontFamily,
}: TypeMorphProps) {
  const frame = useCurrentFrame();
  const { height, width } = useVideoConfig();
  const t = useKitTheme(theme, mode);
  const face = resolveFont(fontFamily ?? t.fontFamily) ?? SANS;
  const paper = background ?? t.background;
  const type = ink ?? t.foreground;
  const fontSize = height * size;

  const typed = lead + emphasis;
  const { probe, offsets } = useGlyphOffsets(
    [typed, emphasis, morphTo, finally_],
    fontSize,
    face,
  );

  // ── the timeline ──────────────────────────────────────────────────────────
  //
  // Absolute frame numbers, measured, not derived from each other. Deriving them
  // meant one wrong constant early shifted everything after it.

  const floodAt = CUT2_AT + 1;
  const floodBAt = floodAt + FLOOD_STAGE_FRAMES;

  const phase =
    flood && frame >= floodAt
      ? "flood"
      : frame >= CUT2_AT
        ? "final"
        : frame >= MORPH_FROM
          ? "morph"
          : frame >= CUT_AT
            ? "slide"
            : "type";

  const floodColor =
    flood && frame >= floodAt
      ? frame >= floodBAt
        ? flood[1]
        : flood[0]
      : null;

  const centre = width / 2;

  /**
   * The line's horizontal offset — ONE continuous function of frame.
   *
   * The reference does not cut and then move; it moves continuously and the cut
   * only changes what is drawn. A single 16-frame cubic-bezier fits all 17
   * frames of the re-centring, straight through the cut, to 0.067px. Modelling
   * it as "drift, cut, slide" fits the same curve twice and puts a seam where
   * the reference has none.
   *
   * The travel is not a fixed distance — it is however far off-centre the
   * emphasis happens to sit inside the typed line, which the measured probe
   * already knows. On the reference that works out to 184.4px right of centre on
   * a 1400px frame; on any other phrase it is whatever that phrase needs.
   */
  const slideProgress = interpolate(frame, [SLIDE_FROM, SLIDE_TO], [0, 1], {
    easing: Easing.bezier(...SLIDE_BEZIER),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  /** The exit: geometric per-frame velocity. Persists past the cut it precedes. */
  //
  // It stops at the cut. The reference carries the drifted position into what
  // the cut leaves behind, but the final phrase here is centred by choice, and a
  // drift still applied to it would drag a centred phrase off to the left — 300px
  // by the last frame.
  const exitDrift =
    frame <= EXIT_FROM || frame >= CUT2_AT
      ? 0
      : (-EXIT_COEFF * (EXIT_RATIO ** (frame - EXIT_FROM) - 1) * width) / 1400;

  /** One glyph, absolutely placed, so nothing reflows as the line changes. */
  const glyph = (
    key: string,
    ch: string,
    x: number,
    lineWidth: number,
    style: CSSProperties,
  ) => (
    <span
      key={key}
      style={{
        position: "absolute",
        left: centre - lineWidth / 2 + x,
        top: 0,
        whiteSpace: "pre",
        ...style,
      }}
    >
      {ch === " " ? " " : ch}
    </span>
  );

  let content: React.ReactNode = null;

  if (offsets) {
    const [typedX, emphX, morphX, finalX] = offsets;
    const widthOf = (xs: number[], str: string) =>
      (xs[str.length - 1] ?? 0) + fontSize * 0.34;

    const wTyped = widthOf(typedX, typed);
    const wEmph = widthOf(emphX, emphasis);
    const wMorph = widthOf(morphX, morphTo);

    // Where the emphasis sits inside the typed line. The slide carries the whole
    // line, so both the typed phase and the post-cut phase read the same offset.
    const emphInTyped = typedX[lead.length] - wTyped / 2 + wEmph / 2;

    if (phase === "type") {
      // `text-reveal` owns these frames entirely — see the render below.
      content = null;
    } else if (phase === "slide") {
      // From the cut to the end of the slide, this component draws the line —
      // `text-reveal` has already delivered it, centred, and the emphasis now
      // slides on the measured bezier.
      const w = widthOf(emphX, emphasis);
      const dx = -emphInTyped * (1 - slideProgress);
      content = [...emphasis].map((ch, i) =>
        glyph(`e${i}`, ch, emphX[i] + dx, w, {
          color: type,
          fontWeight: 700,
        }),
      );
    } else if (phase === "morph") {
      const p = interpolate(frame, [MORPH_FROM, MORPH_TO], [0, 1], {
        easing: EASE,
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      });
      const w = interpolate(p, [0, 1], [wEmph, wMorph]);
      const pairs = pairGlyphs(emphasis, morphTo);
      const matched = new Set(pairs.filter((x): x is number => x !== null));
      content = [
        ...[...emphasis].map((ch, i) =>
          matched.has(i)
            ? null
            : glyph(`x${i}`, ch, emphX[i] + (wEmph - w) / 2, w, {
                color: type,
                fontWeight: 700,
                opacity: interpolate(p, [0, 0.45], [1, 0], {
                  extrapolateRight: "clamp",
                }),
              }),
        ),
        ...[...morphTo].map((ch, i) => {
          const src = pairs[i];
          const to = morphX[i] + (wMorph - w) / 2;
          if (src === null) {
            return glyph(`n${i}`, ch, to, w, {
              color: type,
              fontWeight: 700,
              opacity: interpolate(p, [0.55, 1], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }),
            });
          }
          const fromX = emphX[src] + (wEmph - w) / 2;
          return glyph(`m${i}`, ch, interpolate(p, [0, 1], [fromX, to]), w, {
            color: type,
            fontWeight: 700,
          });
        }),
      ].filter(Boolean);
    } else {
      // The final phrase, CENTRED — it does not inherit the drifted position.
      const w = widthOf(finalX, finally_);
      const hidden = phase === "flood" && !wordOnFlood;
      content = hidden
        ? []
        : [...finally_].map((ch, i) =>
            glyph(`f${i}`, ch, finalX[i], w, {
              fontWeight: 700,
              color: floodColor
                ? mixOklch(floodColor, t.background, 0.92)
                : type,
              opacity: 1,
            }),
          );
    }
  }

  return (
    <AbsoluteFill
      showInTimeline={false}
      style={{
        background: floodColor ?? paper,
        fontFamily: face,
        ...CRISP,
      }}
    >
      {probe}
      {frame < CUT_AT ? (
        <TextReveal
          text={typed}
          fontSize={fontSize}
          color={type}
          theme={theme}
          mode={mode}
          {...reveal}
        />
      ) : null}
      <div
        style={{
          position: "absolute",
          top: "50%",
          left: 0,
          right: 0,
          height: 0,
          fontSize,
          lineHeight: 1,
          letterSpacing: "-0.035em",
          transform: `translate(${exitDrift.toFixed(2)}px, ${-fontSize * 0.36}px)`,
          ...promoted,
        }}
      >
        {content}
      </div>
    </AbsoluteFill>
  );
}

/* ─────────────────────────────────────────────────────────────────────────
   Remotion Studio
   ───────────────────────────────────────────────────────────────────────── */

type TypeMorphElementProps = Omit<
  ComponentProps<typeof TypeMorphScene>,
  | "from"
  | "durationInFrames"
  | "trimBefore"
  | "playbackRate"
  | "loop"
  | "freeze"
  | "hidden"
  | "name"
  | "showInTimeline"
  | "cropLeft"
  | "cropRight"
  | "cropTop"
  | "cropBottom"
  | "premountFor"
  | "postmountFor"
  | "styleWhilePremounted"
  | "styleWhilePostmounted"
  | "controls"
  | "finally_"
> & {
  readonly closing?: ComponentProps<typeof TypeMorphScene>["finally_"];
  readonly style?: CSSProperties;
};

/** What a prop falls back to when Studio does not pass it, reset included. */
const TypeMorphDefaults = {
  lead: "Not just ",
  emphasis: "communicator.",
  morphTo: "something more.",
  closing: "more.",
  background: "transparent",
  ink: "#000000",
} satisfies Partial<TypeMorphElementProps>;

/** The Inspector's controls. Timing, transform, crop and premount come with `wrapInSequence`. */
const TypeMorphSchema = {
  lead: {
    type: "text-content",
    default: "Not just ",
    description: "Lead (cut away)",
  },
  emphasis: {
    type: "text-content",
    default: "communicator.",
    description: "Emphasis",
  },
  morphTo: {
    type: "text-content",
    default: "something more.",
    description: "Morphs into",
  },
  closing: {
    type: "text-content",
    default: "more.",
    description: "Final word",
  },
  ink: {
    type: "color",
    default: "#000000",
    description: "Text",
    keyframable: false,
  },
  fontFamily: { type: "font-family", default: undefined, description: "Font" },
} as const satisfies InteractivitySchema;

/**
 * In over the first frames, out over the last. Opacity only: nothing moves, so
 * no glyph can snap to the pixel grid on the way out.
 */
function TypeMorphFade({ children }: { children: ReactNode }) {
  const frame = useCurrentFrame();
  const enter = Math.min(1, (frame + 1) / 6);
  const { durationInFrames } = useVideoConfig();
  const left = Math.min(1, Math.max(0, (durationInFrames - 1 - frame) / 12));
  const leave = left * left;
  return (
    <AbsoluteFill showInTimeline={false} style={{ opacity: enter * leave }}>
      {children}
    </AbsoluteFill>
  );
}

const TypeMorphInner = forwardRef<HTMLDivElement, TypeMorphElementProps>(
  ({ style, ...props }, ref) => {
    // The layer's length, from the Sequence `wrapInSequence` puts around this.
    const { durationInFrames } = useVideoConfig();
    const { closing, ...rest } = { ...TypeMorphDefaults, ...props };
    // The scene measures its copy once, on mount. An Inspector edit changes the
    // props without remounting it, so the key does.
    const key = JSON.stringify(props, (k, v) =>
      k === "children" ? undefined : v,
    );

    // width/height are what useVideoConfig() reports inside this Sequence, so
    // the scene lays itself out in its stage rather than the whole composition.
    // It is not a layer of its own: the one Studio shows is the wrapper's.
    return (
      <Sequence
        layout="none"
        showInTimeline={false}
        durationInFrames={durationInFrames}
        width={1280}
        height={720}
      >
        <div
          ref={ref}
          style={{
            position: "relative",
            width: 1280,
            height: 220,
            overflow: "hidden",
            color: "black",
            fontFamily: "initial",
            fontSize: 16,
            fontStyle: "normal",
            fontVariant: "normal",
            fontWeight: 400,
            fontStretch: "normal",
            fontKerning: "auto",
            fontFeatureSettings: "normal",
            fontVariationSettings: "normal",
            lineHeight: "normal",
            letterSpacing: "normal",
            wordSpacing: "normal",
            textAlign: "start",
            textIndent: 0,
            textTransform: "none",
            textShadow: "none",
            textRendering: "auto",
            whiteSpace: "normal",
            wordBreak: "normal",
            overflowWrap: "normal",
            hyphens: "manual",
            direction: "ltr",
            visibility: "visible",
            ...style,
          }}
        >
          <div
            style={{
              position: "absolute",
              left: 0,
              top: -230,
              width: 1280,
              height: 720,
            }}
          >
            <TypeMorphFade>
              <TypeMorphScene key={key} {...rest} finally_={closing} />
            </TypeMorphFade>
          </div>
        </div>
      </Sequence>
    );
  },
);

export const TypeMorph = Interactive.withSchema({
  Component: TypeMorphInner,
  componentName: "<TypeMorph>",
  schema: TypeMorphSchema,
  wrapInSequence: true,
});
